// ─────────────────────────────────────────────────────────────────────────────
// Shared Helpers
// ─────────────────────────────────────────────────────────────────────────────
/**
 * Loads API key and agent ID, failing with clear error if not configured.
 */
async function loadAuthOrFail() {
    const { config, agentId, apiKey } = await initializeCommand({ showProgress: false });
    return { apiKey, agentId, config };
}
/**
 * Prompts user to select a tool from the list.
 */
async function promptToolSelection(tools) {
    const toolChoices = tools.map((tool) => ({
        name: tool.skillName
            ? `${tool.name} (${tool.skillName}) - ${tool.description}`
            : `${tool.name} - ${tool.description}`,
        value: tool
    }));
    const { selectedTool } = await inquirer.prompt([
        {
            type: 'list',
            name: 'selectedTool',
            message: '🔧 Select a tool to test:',
            choices: toolChoices,
            pageSize: 10
        }
    ]);
    return selectedTool;
}
/**
 * Wraps execution with sandbox environment (env vars setup/teardown).
 */
async function withSandboxEnv(fn) {
    const envVars = loadEnvironmentVariables();
    const originalEnv = { ...process.env };
    for (const [key, value] of Object.entries(envVars)) {
        process.env[key] = value;
    }
    try {
        return await fn();
    }
    finally {
        process.env = originalEnv;
    }
}
/**
 * Parses JSON input, failing with formatted error message.
 */
function parseJsonInputOrFail(inputJson, expectedFormat) {
    try {
        return JSON.parse(inputJson);
    }
    catch (error) {
        console.error(`❌ Invalid JSON input: ${error instanceof Error ? error.message : 'Unknown error'}`);
        console.log(`Expected format: ${expectedFormat}`);
        throw new Error(`Invalid JSON input: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
}
/**
 * Selects an entity by name (non-interactive) or prompts user (interactive).
 */
async function selectEntityOrPrompt(options) {
    const { items, entityName, entityType, idProperty, nameProperty, promptMessage, formatChoice } = options;
    if (entityName) {
        const selected = items.find((item) => item[idProperty] === entityName || item[nameProperty] === entityName);
        if (!selected) {
            console.error(`❌ ${entityType} "${entityName}" not found`);
            throw new Error("${entityType}");
        }
        writeProgress(`✅ Selected ${entityType.toLowerCase()}: ${selected[nameProperty]}`);
        return selected;
    }
    const answer = await safePrompt([
        {
            type: 'list',
            name: 'selected',
            message: promptMessage,
            choices: items.map((item) => ({
                name: formatChoice ? formatChoice(item) : `${item[nameProperty]}`,
                value: item
            }))
        }
    ]);
    if (!answer)
        return null;
    return answer.selected;
}
/**
 * Handles execution errors with consistent formatting.
 */
function handleExecutionError(error, entityType) {
    console.error(`\n❌ ${entityType} execution failed:`);
    console.error(error.message);
    if (error.stack) {
        console.error(error.stack);
    }
}
/**
 * Extracts all tools from manifest (grouped by skill).
 */
function extractToolsFromManifest(manifest) {
    const tools = getPrimitivesByKind(manifest, PrimitiveKind.TOOL);
    const skills = getPrimitivesByKind(manifest, PrimitiveKind.SKILL);
    // Create a map of tool name to skill name
    const toolToSkill = new Map();
    for (const skill of skills) {
        for (const toolName of skill.tools || []) {
            toolToSkill.set(toolName, skill.name);
        }
    }
    return tools.map(tool => ({
        ...tool,
        id: tool.name,
        skillName: toolToSkill.get(tool.name) || 'unknown',
    }));
}
