async function testPreProcessor(entityName, inputJson) {
    writeProgress("📥 Testing preprocessor...");
    writeProgress("📦 Compiling code first...");
    await compileCommand();
    const manifest = loadManifest();
    const preprocessors = getPrimitivesByKind(manifest, PrimitiveKind.PREPROCESSOR);
    if (preprocessors.length === 0) {
        console.error("❌ No preprocessors found in compiled output.");
        return;
    }
    // Select preprocessor
    const selected = await selectEntityOrPrompt({
        items: preprocessors,
        entityName,
        entityType: 'Preprocessor',
        idProperty: 'name',
        nameProperty: 'name',
        promptMessage: 'Select a preprocessor to test:',
        formatChoice: (p) => `${p.name}`
    });
    if (!selected)
        return;
    // Get inputs
    let message;
    let channel;
    if (inputJson) {
        const input = parseJsonInputOrFail(inputJson, '{"message": "text", "channel": "channel_name"}');
        message = input.message || 'Hello, I need help with my order';
        channel = input.channel || 'web';
    }
    else {
        const messageAnswer = await safePrompt([
            { type: 'input', name: 'message', message: 'Enter test message:', default: 'Hello, I need help with my order' }
        ]);
        if (!messageAnswer)
            return;
        message = messageAnswer.message;
        const channelAnswer = await safePrompt([
            { type: 'input', name: 'channel', message: 'Enter channel:', default: 'web' }
        ]);
        if (!channelAnswer)
            return;
        channel = channelAnswer.channel;
    }
    // Execute
    writeProgress("\n🚀 Executing preprocessor...");
    writeProgress(`Input message: ${message}`);
    writeProgress(`Channel: ${channel}`);
    const { apiKey, agentId } = await loadAuthOrFail();
    const preprocessorCode = loadArtifact(selected, process.cwd());
    await withSandboxEnv(async () => {
        try {
            const messages = [{ type: 'text', text: message }];
            const result = await executePreProcessor({
                processorCode: preprocessorCode,
                messages,
                channel,
                apiKey,
                agentId
            });
            writeSuccess("\n✅ PreProcessor execution successful!");
            // Helper to display messages
            const displayMessages = (outputMessages) => {
                console.log(`Processed messages (${outputMessages.length}):`);
                outputMessages.forEach((msg, idx) => {
                    if (msg.type === 'text') {
                        console.log(`  ${idx + 1}. [TEXT] ${msg.text}`);
                    }
                    else if (msg.type === 'image') {
                        console.log(`  ${idx + 1}. [IMAGE] ${msg.mimeType}`);
                    }
                    else if (msg.type === 'file') {
                        console.log(`  ${idx + 1}. [FILE] ${msg.mimeType}`);
                    }
                    else {
                        console.log(`  ${idx + 1}. [${msg.type}]`, msg);
                    }
                });
            };
            if (result.action === 'block') {
                console.log(`\nAction: BLOCK`);
                console.log(`Response: ${result.response}`);
                if (result.metadata) {
                    console.log(`Metadata: ${JSON.stringify(result.metadata, null, 2)}`);
                }
            }
            else if (result.action === 'proceed') {
                console.log(`\nAction: PROCEED`);
                const outputMessages = result.modifiedMessage || messages;
                displayMessages(outputMessages);
                if (result.metadata) {
                    console.log(`Metadata: ${JSON.stringify(result.metadata, null, 2)}`);
                }
            }
            else {
                console.log(`\nAction: PROCEED (no valid action returned, messages unchanged)`);
                displayMessages(messages);
                console.log(`\nRaw result: ${JSON.stringify(result, null, 2)}`);
            }
        }
        catch (error) {
            handleExecutionError(error, 'PreProcessor');
        }
    });
}
